    c6 VARCHAR(255),
    c9 INT,
    c3 INT,
    c5 VARCHAR(255)
);

CREATE TABLE table1 (
    c4 INT,
    c6 VARCHAR(255),
    c2 VARCHAR(255)
);

CREATE TABLE table2 (
    c8 INT,
    c4 INT,
    c10 INT,
    c7 VARCHAR(255),
    c1 INT
);

counterexample:
-- Insert duplicate rows into table3
INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (1, 'BLUE', 10, 100, 'x');
INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (1, 'BLUE', 20, 200, 'y');

-- Create a red row in table1 and a table2 row that joins with it but for a different c10
INSERT INTO table1 (c4, c6, c2) VALUES (100, 'RED', 'alpha');
INSERT INTO table2 (c8, c4, c10, c7, c1) VALUES (500, 100, 2, 'foo', 1);

-- Explanation:
-- The table3 rows have c10 = 1. In the subqueries of both Q1 and Q2, the only red record found (from the join between table2 and table1) is for c10 = 2. Hence, both queries treat the table3 rows as qualifying.
-- Q1 returns two rows with 'BLUE' (one for each table3 insertion) while Q2 returns DISTINCT 'BLUE'. This difference shows that the queries are not equivalent.

