counterexample:
/* Note: This counterexample assumes a version of the data where table1 is allowed to have multiple rows with the same c1. Under the given schema (with PRIMARY KEY on c1) such a situation cannot occur, but the example demonstrates the logic difference. */

-- Insert into table2
INSERT INTO table2 (c2) VALUES (1);
INSERT INTO table2 (c2) VALUES (2);

-- Hypothetical inserts into table1 (if the PK on c1 were not present) so that the same group (say group 1) has two rows
INSERT INTO table1 (c1, c2) VALUES (1, 1);
INSERT INTO table1 (c1, c2) VALUES (1, 2);

-- In Q1, the group for c1=1 has COUNT(DISTINCT c2)=2 which matches COUNT(DISTINCT c2) from table2 (which is 2).
-- In Q2, however, the group for c1=1 may yield GROUP_CONCAT(DISTINCT c2) = '2,1' while the subquery might yield '1,2', so the equality fails.

