schema:
CREATE TABLE table1 (
    c1 INT,
    c2 INT,
    c3 INT,
    c4 DATE
);

CREATE TABLE table1 (
    c1 INT,
    c3 VARCHAR(255),
    c2 INT,
    PRIMARY KEY (c1),
    CHECK (c2 >= 0)
);
CREATE TABLE table2 (
    c4 INT,
    c1 INT,
    PRIMARY KEY (c4, c1),
    FOREIGN KEY (c1) REFERENCES table1(c1)
);

CREATE TABLE table1 (
    c2 INT,
    c1 BOOLEAN
);

counterexample:
INSERT INTO table1 (c2, c1) VALUES (1, 1);
INSERT INTO table1 (c2, c1) VALUES (2, 1);
INSERT INTO table1 (c2, c1) VALUES (2, 1);

